const r = await tools.exec_command({cmd:"perl -0777 -e '
my %want;
open my $tf, "<", "/tmp/tag_local_targets.tsv" or die $!;
while (<$tf>) { chomp; my ($name,$file,$tag)=split /\t/; my $short=$name; $short =~ s/^.*\.//; push @{$want{$file}}, [$short,$tag,$name]; }
for my $file (sort keys %want) {
  open my $fh, "<", $file or die "$file: $!"; local $/; my $s=<$fh>; close $fh;
  for my $entry (@{$want{$file}}) {
    my ($short,$tag,$name)=@$entry;
    my @m; while ($s =~ /^[ \t]*(?:(?:noncomputable|protected)[ \t]+)*(?:theorem|lemma|def|abbrev|instance)[ \t]+\Q$short\E\b/mg) { push @m, $-[0]; }
    die "expected one declaration for $name in $file, found " . scalar(@m) . "\n" unless @m == 1;
    my $p=$m[0];
    my $before=substr($s,0,$p); my $close=rindex($before,"-/");
    my $inserted=0;
    if ($close >= 0 && substr($before,$close+2) =~ /^\s*\z/s) {
      my $pre=substr($before,0,$close); my $open=rindex($pre,"/-");
      if ($open >= 0 && substr($pre,$open,3) eq "/--") {
        my $doc=substr($pre,$open);
        die "duplicate provenance in $name\n" if $doc =~ /Provenance:/;
        substr($s,$close,0)="\n * Provenance: $tag.\n"; $inserted=1;
      }
    }
    if (!$inserted) { substr($s,$p,0)="/-- Provenance: $tag. -/\n"; }
  }
  open my $out, ">", $file or die "$file: $!"; print {$out} $s; close $out;
}
' $(cut -f2 /tmp/tag_local_targets.tsv | sort -u)
